        case (_: BoolArg, _: KindBool) => true
        case (_: DimArg, _: KindDim) => true
        case (_: OpArg, _: KindOp) => true
        case (_: UnitArg, _: KindUnit) => true
        case (_: IntArg, _: KindNat) => true
        case (_, _) => false
      }
    }

    // Match every pair.
